<?php
/**
 * XML feed for allmarket.biz:
 * index.php?fc=module&module=allmarketsync&controller=feed&token=...&type=full|offers
 *
 * Serves the file generated by cron; builds it on the fly if missing or stale.
 *
 * @author    allmarket.biz
 * @copyright 2026 allmarket.biz
 * @license   Commercial
 */
if (!defined('_PS_VERSION_')) {
    exit;
}

class AllmarketsyncFeedModuleFrontController extends ModuleFrontController
{
    /** Regenerate on request if the cached file is older than this (seconds). */
    const MAX_AGE = ['full' => 86400, 'offers' => 3600];

    public $auth = false;
    public $guestAllowed = true;
    public $ajax = true;

    public function postProcess()
    {
        $token = (string) Tools::getValue('token');
        if ($token === '' || !hash_equals((string) Configuration::get('ALLMARKET_FEED_TOKEN'), $token)) {
            header('HTTP/1.1 403 Forbidden');
            exit('Forbidden');
        }

        $type = Tools::getValue('type') === 'offers' ? 'offers' : 'full';
        $idShop = (int) $this->context->shop->id;
        $path = AllmarketFeed::path($type, $idShop);

        if (!is_file($path) || filemtime($path) < time() - self::MAX_AGE[$type]) {
            try {
                (new AllmarketExchange($this->module, $idShop))->generateFeeds([$type]);
            } catch (Exception $e) {
                AllmarketLog::error('feed', $e->getMessage());
                if (!is_file($path)) {
                    header('HTTP/1.1 503 Service Unavailable');
                    exit('Feed is not available');
                }
            }
        }

        $mtime = filemtime($path);
        header('Content-Type: application/xml; charset=utf-8');
        header('Last-Modified: ' . gmdate('D, d M Y H:i:s', $mtime) . ' GMT');
        header('Content-Length: ' . filesize($path));
        header('X-Robots-Tag: noindex');
        if (isset($_SERVER['HTTP_IF_MODIFIED_SINCE']) && strtotime($_SERVER['HTTP_IF_MODIFIED_SINCE']) >= $mtime) {
            header('HTTP/1.1 304 Not Modified');
            exit;
        }
        readfile($path);
        exit;
    }
}
